// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount > 0);
        vm.assume(amount < 1 ether);
        address target = address(new Target());
        vm.deal(address(c), 10 ether);
        vm.deal(address(this), amount);
        uint256 beforeBal = target.balance;
        c.Command{value: amount}(target, "");
        uint256 afterBal = target.balance;
        assertTrue(afterBal - beforeBal >= amount);
    }
}

contract Target {
    receive() external payable {}
}
